<template><div class="page-title">销售与服务总览</div><div class="card-grid"><el-card class="metric" v-for="m in metrics" :key="m.label"><div>{{m.label}}</div><div class="num">{{m.value}}</div></el-card></div><div class="charts"><el-card><template #header>商机漏斗</template><div ref="pipelineEl" class="chart"/></el-card><el-card><template #header>线索来源</template><div ref="sourceEl" class="chart"/></el-card><el-card><template #header>工单状态</template><div ref="caseEl" class="chart"/></el-card><el-card><template #header>最近活动</template><el-timeline><el-timeline-item v-for="x in recent" :key="x.id">{{x.subject}} <small>{{x.status}}</small></el-timeline-item></el-timeline></el-card></div></template>
<script setup>import {ref,onMounted} from 'vue';import * as echarts from 'echarts';import {dashboard} from '../api';import {text,maps} from '../utils/enums';const metrics=ref([]),recent=ref([]),pipelineEl=ref(),sourceEl=ref(),caseEl=ref();onMounted(async()=>{try{const d=await dashboard.summary();metrics.value=[{label:'新增线索',value:d.newLeadCount},{label:'进行中商机',value:d.openOpportunityCount},{label:'商机金额',value:d.openOpportunityAmount||0},{label:'待处理工单',value:d.openCaseCount}];recent.value=d.recentActivities||[];new echarts.init(pipelineEl.value).setOption({tooltip:{},xAxis:{type:'category',data:(d.pipeline||[]).map(x=>text(maps.stage,x.stage))},yAxis:{type:'value'},series:[{type:'bar',data:(d.pipeline||[]).map(x=>x.count),itemStyle:{color:'#409eff'}}]});new echarts.init(sourceEl.value).setOption({tooltip:{},series:[{type:'pie',radius:'65%',data:Object.entries(d.leadBySource||{}).map(([name,value])=>({name,value}))}]});new echarts.init(caseEl.value).setOption({xAxis:{type:'category',data:Object.keys(d.caseByStatus||{}).map(x=>text(maps.caseStatus,x))},yAxis:{type:'value'},series:[{type:'bar',data:Object.values(d.caseByStatus||{}),itemStyle:{color:'#67c23a'}}]})}catch(e){}})</script>
